	static final AtomicLong COMPILE_FAILURES = new AtomicLong();
	static final AtomicLong COMPILE_NANOS = new AtomicLong();
	static final AtomicLong KERNEL_INSTANTIATIONS = new AtomicLong();
	static final AtomicLong CACHE_HITS = new AtomicLong();
	static final AtomicLong CACHE_MISSES = new AtomicLong();
	static final AtomicLong EVICTIONS = new AtomicLong();
	static final AtomicLong FALLBACKS = new AtomicLong();

